"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7833],{89046:e=>{e.exports=JSON.parse('{"functions":[{"name":"resolveUDim","desc":"Converts a UDim to pixels: `Offset + Scale * referenceSize`.","params":[{"name":"size","desc":"","lua_type":"UDim"},{"name":"referenceSize","desc":"The size, in pixels, that `Scale` is relative to.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":31,"path":"src/LayoutUtil.luau"}},{"name":"FixScrollingCanvas","desc":"Turns off `AutomaticCanvasSize` and keeps `CanvasSize` fitted to the layout\'s\\ncontent plus any padding, never smaller than the visible window. Only the axes\\nthe frame scrolls on are sized; the other axis is set to 0.\\n\\nUpdates are batched to the next Heartbeat after a child is added or removed, the\\ncontent or window size changes, the scrolling direction changes, or the padding\\nchanges.","params":[{"name":"layout","desc":"The UIListLayout or UIGridLayout inside the frame.","lua_type":"UIGridStyleLayout"},{"name":"scrollingFrame","desc":"","lua_type":"ScrollingFrame"},{"name":"padding","desc":"Padding to add around the content.","lua_type":"UIPadding?"}],"returns":[{"desc":"Stops updating the canvas.","lua_type":"() -> ()"}],"function_type":"static","realm":["Client"],"source":{"line":93,"path":"src/LayoutUtil.luau"}},{"name":"FixAuthoredListHeights","desc":"Locks each item and the layout\'s padding to the height they were authored with,\\nresolved against the scrolling frame\'s visible height. Scale heights then stay\\nrelative to the viewport instead of growing with the canvas. Each item gets a\\nUISizeConstraint, and the layout\'s `Padding` is rewritten in pixels whenever the\\nwindow resizes.","params":[{"name":"scrollingFrame","desc":"","lua_type":"ScrollingFrame"},{"name":"layout","desc":"","lua_type":"UIListLayout"},{"name":"items","desc":"The list items, whose current `Size.Y` is kept.","lua_type":"{ GuiObject }"}],"returns":[{"desc":"Disconnects and destroys the size constraints. The layout\'s padding is not restored.","lua_type":"() -> ()"}],"function_type":"static","realm":["Client"],"source":{"line":160,"path":"src/LayoutUtil.luau"}},{"name":"FixLayout","desc":"Adds a UIAspectRatioConstraint to each visible item in the scrolling frame and\\nkeeps the vertical canvas fitted to the content plus any top and bottom padding.\\nItems added later are constrained as they arrive. Items that already have a\\nUIAspectRatioConstraint of their own are left alone.\\n\\n`itemAspectRatio` decides the ratio:\\n- a positive number is used for every item;\\n- a UDim2 is converted to a ratio once, against the frame\'s canvas size minus padding;\\n- any other number (0, negative or infinite) gives each item the ratio of its own\\n  `Size` against the frame\'s size, re-applied whenever the frame resizes;\\n- nil adds no constraints and only fixes the canvas.","params":[{"name":"layout","desc":"","lua_type":"UIGridStyleLayout"},{"name":"scrollingFrame","desc":"","lua_type":"ScrollingFrame"},{"name":"itemAspectRatio","desc":"","lua_type":"(number | UDim2)?"},{"name":"padding","desc":"","lua_type":"UIPadding?"}],"returns":[{"desc":"Disconnects and destroys the constraints this call created.","lua_type":"() -> ()"}],"function_type":"static","realm":["Client"],"source":{"line":219,"path":"src/LayoutUtil.luau"}}],"properties":[],"types":[],"name":"LayoutUtil","desc":"Keeps ScrollingFrame canvases and their items sized correctly as content and\\nscreen size change. Each `Fix*` function returns a cleanup function that\\ndisconnects everything it set up.\\n\\n```lua\\nlocal cleanup = LayoutUtil.FixScrollingCanvas(list.UIListLayout, list, list:FindFirstChildOfClass(\\"UIPadding\\"))\\n\\n-- When the UI is destroyed\\ncleanup()\\n```","source":{"line":16,"path":"src/LayoutUtil.luau"}}')}}]);